#[cfg(test)]
mod tests {
    use super::*;

    fn hex_rgba(h: &str) -> u32 {
        let h = h.trim_start_matches('#');
        u32::from_str_radix(&if h.len() == 6 { format!("{h}FF") } else { h.to_string() }, 16).unwrap()
    }

    /// Every variable of `docs/redesign/tokens.json` is a constant here with the same Dark and Light value.
    #[test]
    fn constants_match_tokens_json() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../docs/redesign/tokens.json");
        let json: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
        let (mut colors, mut sizes) = (0, 0);
        for coll in json["collections"].as_array().unwrap() {
            for v in coll["variables"].as_array().unwrap() {
                let name = v["name"].as_str().unwrap();
                if let Some(values) = v.get("values") {
                    let t = ALL_COLORS.iter().find(|(n, _)| *n == name).unwrap_or_else(|| panic!("missing {name}")).1;
                    assert_eq!(t.rgba(true), hex_rgba(values["Dark"].as_str().unwrap()), "{name} Dark");
                    assert_eq!(t.rgba(false), hex_rgba(values["Light"].as_str().unwrap()), "{name} Light");
                    colors += 1;
                } else {
                    let s = ALL_NUMBERS.iter().find(|(n, _)| *n == name).unwrap_or_else(|| panic!("missing {name}")).1;
                    assert_eq!(f64::from(s), v["value"].as_f64().unwrap(), "{name}");
                    sizes += 1;
                }
            }
        }
        assert_eq!((colors, sizes), (ALL_COLORS.len(), ALL_NUMBERS.len()));
    }
}
